import { batch } from "solid-js";
import { ChannelUnread } from "../classes/ChannelUnread.js";
import { ClassCollection } from "./Collection.js";
/**
 * Collection of Channel Unreads
 */
export class ChannelUnreadCollection extends ClassCollection {
    #syncPromise;
    #retryTimeout;
    #getRetryAfterMs(error) {
        if (typeof error === "object" &&
            error !== null &&
            "retry_after" in error &&
            typeof error.retry_after === "number") {
            return Math.max(250, error.retry_after);
        }
        return 2000;
    }
    #isRetryAfterError(error) {
        return (typeof error === "object" &&
            error !== null &&
            "retry_after" in error &&
            typeof error.retry_after === "number");
    }
    #scheduleRetry(delay) {
        clearTimeout(this.#retryTimeout);
        this.#retryTimeout = setTimeout(() => {
            void this.sync().catch((error) => {
                if (!this.#isRetryAfterError(error)) {
                    console.error("[channelUnreads] sync retry failed", error);
                }
            });
        }, delay);
    }
    /**
     * Load unread information from server
     */
    async sync() {
        if (this.#syncPromise) {
            return this.#syncPromise;
        }
        this.#syncPromise = (async () => {
            try {
                const unreads = await this.client.api.get("/sync/unreads");
                batch(() => {
                    this.reset();
                    for (const unread of unreads) {
                        this.getOrCreate(unread._id.channel, unread);
                    }
                });
            }
            catch (error) {
                const retryIn = this.#getRetryAfterMs(error);
                this.#scheduleRetry(retryIn);
                if (!this.#isRetryAfterError(error)) {
                    throw error;
                }
                return;
            }
            finally {
                this.#syncPromise = undefined;
            }
        })();
        return this.#syncPromise;
    }
    /**
     * Clear all unread data
     */
    reset() {
        this.updateUnderlyingObject({});
    }
    /**
     * Get or create
     * @param id Id
     * @param data Data
     */
    getOrCreate(id, data) {
        if (this.has(id)) {
            return this.get(id);
        }
        else {
            const instance = new ChannelUnread(this, id);
            this.create(id, "channelUnread", instance, this.client, data);
            return instance;
        }
    }
    /**
     * Get channel unread data for a specific Channel
     * @param channel Channel
     * @returns Unread
     */
    for(channel) {
        return this.getOrCreate(channel.id, {
            _id: {
                channel: channel.id,
                user: this.client.user.id,
            },
            last_id: null,
            mentions: [],
        });
    }
}
